26	/// A directory entry with a possible error attached.
27	///
28	/// The error typically refers to a problem parsing ignore files in a
29	/// particular directory.
30	#[derive(Clone, Debug)]
31	pub struct DirEntry {
32	    dent: DirEntryInner,
33	    err: Option<Error>,
34	}
35	
36	impl DirEntry {
37	    /// The full path that this entry represents.
38	    pub fn path(&self) -> &Path {
39	        self.dent.path()
40	    }
41	
42	    /// The full path that this entry represents.
43	    /// Analogous to [`DirEntry::path`], but moves ownership of the path.
44	    pub fn into_path(self) -> PathBuf {
45	        self.dent.into_path()
46	    }
47	
48	    /// Whether this entry corresponds to a symbolic link or not.
49	    pub fn path_is_symlink(&self) -> bool {
50	        self.dent.path_is_symlink()
51	    }
52	
53	    /// Returns true if and only if this entry corresponds to stdin.
54	    ///
55	    /// i.e., The entry has depth 0 and its file name is `-`.
56	    pub fn is_stdin(&self) -> bool {
57	        self.dent.is_stdin()
58	    }
59	
60	    /// Return the metadata for the file that this entry points to.
61	    pub fn metadata(&self) -> Result<Metadata, Error> {
62	        self.dent.metadata()
63	    }
64	
65	    /// Return the file type for the file that this entry points to.
66	    ///
67	    /// This entry doesn't have a file type if it corresponds to stdin.
68	    pub fn file_type(&self) -> Option<FileType> {
69	        self.dent.file_type()
70	    }
71	
72	    /// Return the file name of this entry.
73	    ///
74	    /// If this entry has no file name (e.g., `/`), then the full path is
75	    /// returned.
76	    pub fn file_name(&self) -> &OsStr {
77	        self.dent.file_name()
78	    }
79	
80	    /// Returns the depth at which this entry was created relative to the root.
81	    pub fn depth(&self) -> usize {
82	        self.dent.depth()
83	    }
84	
85	    /// Returns the underlying inode number if one exists.
86	    ///
87	    /// If this entry doesn't have an inode number, then `None` is returned.
88	    #[cfg(unix)]
89	    pub fn ino(&self) -> Option<u64> {
90	        self.dent.ino()
91	    }
92	
93	    /// Returns an error, if one exists, associated with processing this entry.
94	    ///
95	    /// An example of an error is one that occurred while parsing an ignore
96	    /// file. Errors related to traversing a directory tree itself are reported
97	    /// as part of yielding the directory entry, and not with this method.
98	    pub fn error(&self) -> Option<&Error> {
99	        self.err.as_ref()
100	    }
101	
102	    /// Returns true if and only if this entry points to a directory.
103	    pub(crate) fn is_dir(&self) -> bool {
104	        self.dent.is_dir()
105	    }
