120	/// DirEntryInner is the implementation of DirEntry.
121	///
122	/// It specifically represents three distinct sources of directory entries:
123	///
124	/// 1. From the walkdir crate.
125	/// 2. Special entries that represent things like stdin.
126	/// 3. From a path.
127	///
128	/// Specifically, (3) has to essentially re-create the DirEntry implementation
129	/// from WalkDir.
130	#[derive(Clone, Debug)]
131	enum DirEntryInner {
132	    Stdin,
133	    Walkdir(walkdir::DirEntry),
134	    Raw(DirEntryRaw),
135	}
136	
137	impl DirEntryInner {
138	    fn path(&self) -> &Path {
139	        use self::DirEntryInner::*;
140	        match *self {
141	            Stdin => Path::new("<stdin>"),
142	            Walkdir(ref x) => x.path(),
143	            Raw(ref x) => x.path(),
144	        }
145	    }
146	
147	    fn into_path(self) -> PathBuf {
148	        use self::DirEntryInner::*;
149	        match self {
150	            Stdin => PathBuf::from("<stdin>"),
151	            Walkdir(x) => x.into_path(),
152	            Raw(x) => x.into_path(),
153	        }
154	    }
155	
156	    fn path_is_symlink(&self) -> bool {
157	        use self::DirEntryInner::*;
158	        match *self {
159	            Stdin => false,
160	            Walkdir(ref x) => x.path_is_symlink(),
161	            Raw(ref x) => x.path_is_symlink(),
162	        }
163	    }
164	
165	    fn is_stdin(&self) -> bool {
166	        match *self {
167	            DirEntryInner::Stdin => true,
168	            _ => false,
169	        }
170	    }
171	
172	    fn metadata(&self) -> Result<Metadata, Error> {
173	        use self::DirEntryInner::*;
174	        match *self {
175	            Stdin => {
176	                let err = Error::Io(io::Error::new(
177	                    io::ErrorKind::Other,
178	                    "<stdin> has no metadata",
179	                ));
180	                Err(err.with_path("<stdin>"))
181	            }
182	            Walkdir(ref x) => x.metadata().map_err(|err| {
183	                Error::Io(io::Error::from(err))
184	                    .with_depth(x.depth())
185	                    .with_path(x.path())
186	            }),
187	            Raw(ref x) => x.metadata(),
188	        }
189	    }
190	
191	    fn file_type(&self) -> Option<FileType> {
192	        use self::DirEntryInner::*;
193	        match *self {
194	            Stdin => None,
195	            Walkdir(ref x) => Some(x.file_type()),
196	            Raw(ref x) => Some(x.file_type()),
197	        }
198	    }
199	
200	    fn file_name(&self) -> &OsStr {
201	        use self::DirEntryInner::*;
202	        match *self {
203	            Stdin => OsStr::new("<stdin>"),
204	            Walkdir(ref x) => x.file_name(),
205	            Raw(ref x) => x.file_name(),
206	        }
207	    }
208	
209	    fn depth(&self) -> usize {
210	        use self::DirEntryInner::*;
211	        match *self {
212	            Stdin => 0,
213	            Walkdir(ref x) => x.depth(),
214	            Raw(ref x) => x.depth(),
215	        }
216	    }
217	
218	    #[cfg(unix)]
219	    fn ino(&self) -> Option<u64> {
220	        use self::DirEntryInner::*;
221	        use walkdir::DirEntryExt;
222	        match *self {
223	            Stdin => None,
224	            Walkdir(ref x) => Some(x.ino()),
225	            Raw(ref x) => Some(x.ino()),
226	        }
227	    }
228	
229	    /// Returns true if and only if this entry points to a directory.
230	    fn is_dir(&self) -> bool {
231	        self.file_type().map(|ft| ft.is_dir()).unwrap_or(false)
232	    }
233	}
