235	/// DirEntryRaw is essentially copied from the walkdir crate so that we can
236	/// build `DirEntry`s from whole cloth in the parallel iterator.
237	#[derive(Clone)]
238	struct DirEntryRaw {
239	    /// The path as reported by the `fs::ReadDir` iterator (even if it's a
240	    /// symbolic link).
241	    path: PathBuf,
242	    /// The file type. Necessary for recursive iteration, so store it.
243	    ty: FileType,
244	    /// Is set when this entry was created from a symbolic link and the user
245	    /// expects the iterator to follow symbolic links.
246	    follow_link: bool,
247	    /// The depth at which this entry was generated relative to the root.
248	    depth: usize,
249	    /// The underlying inode number (Unix only).
250	    #[cfg(unix)]
251	    ino: u64,
252	    /// The underlying metadata (Windows only). We store this on Windows
253	    /// because this comes for free while reading a directory.
254	    #[cfg(windows)]
255	    metadata: fs::Metadata,
256	}
257	
258	impl std::fmt::Debug for DirEntryRaw {
259	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
260	        // Leaving out FileType because it doesn't have a debug impl
261	        // in Rust 1.9. We could add it if we really wanted to by manually
262	        // querying each possibly file type. Meh. ---AG
263	        f.debug_struct("DirEntryRaw")
264	            .field("path", &self.path)
265	            .field("follow_link", &self.follow_link)
266	            .field("depth", &self.depth)
267	            .finish()
268	    }
269	}
