439	/// WalkBuilder builds a recursive directory iterator.
440	///
441	/// The builder supports a large number of configurable options. This includes
442	/// specific glob overrides, file type matching, toggling whether hidden
443	/// files are ignored or not, and of course, support for respecting gitignore
444	/// files.
445	///
446	/// By default, all ignore files found are respected. This includes `.ignore`,
447	/// `.gitignore`, `.git/info/exclude` and even your global gitignore
448	/// globs, usually found in `$XDG_CONFIG_HOME/git/ignore`.
449	///
450	/// Some standard recursive directory options are also supported, such as
451	/// limiting the recursive depth or whether to follow symbolic links (disabled
452	/// by default).
453	///
454	/// # Ignore rules
455	///
456	/// There are many rules that influence whether a particular file or directory
457	/// is skipped by this iterator. Those rules are documented here. Note that
458	/// the rules assume a default configuration.
459	///
460	/// * First, glob overrides are checked. If a path matches a glob override,
461	/// then matching stops. The path is then only skipped if the glob that matched
462	/// the path is an ignore glob. (An override glob is a whitelist glob unless it
463	/// starts with a `!`, in which case it is an ignore glob.)
464	/// * Second, ignore files are checked. Ignore files currently only come from
465	/// git ignore files (`.gitignore`, `.git/info/exclude` and the configured
466	/// global gitignore file), plain `.ignore` files, which have the same format
467	/// as gitignore files, or explicitly added ignore files. The precedence order
468	/// is: `.ignore`, `.gitignore`, `.git/info/exclude`, global gitignore and
469	/// finally explicitly added ignore files. Note that precedence between
470	/// different types of ignore files is not impacted by the directory hierarchy;
471	/// any `.ignore` file overrides all `.gitignore` files. Within each precedence
472	/// level, more nested ignore files have a higher precedence than less nested
473	/// ignore files.
474	/// * Third, if the previous step yields an ignore match, then all matching
475	/// is stopped and the path is skipped. If it yields a whitelist match, then
476	/// matching continues. A whitelist match can be overridden by a later matcher.
477	/// * Fourth, unless the path is a directory, the file type matcher is run on
478	/// the path. As above, if it yields an ignore match, then all matching is
479	/// stopped and the path is skipped. If it yields a whitelist match, then
480	/// matching continues.
481	/// * Fifth, if the path hasn't been whitelisted and it is hidden, then the
482	/// path is skipped.
483	/// * Sixth, unless the path is a directory, the size of the file is compared
484	/// against the max filesize limit. If it exceeds the limit, it is skipped.
485	/// * Seventh, if the path has made it this far then it is yielded in the
486	/// iterator.
487	#[derive(Clone)]
488	pub struct WalkBuilder {
489	    paths: Vec<PathBuf>,
490	    ig_builder: IgnoreBuilder,
491	    max_depth: Option<usize>,
492	    min_depth: Option<usize>,
493	    max_filesize: Option<u64>,
494	    follow_links: bool,
495	    same_file_system: bool,
496	    sorter: Option<Sorter>,
497	    threads: usize,
498	    skip: Option<Arc<Handle>>,
499	    filter: Option<Filter>,
500	    /// The directory that gitignores should be interpreted relative to.
501	    ///
502	    /// Usually this is the directory containing the gitignore file. But in
503	    /// some cases, like for global gitignores or for gitignores specified
504	    /// explicitly, this should generally be set to the current working
505	    /// directory. This is only used for global gitignores or "explicit"
506	    /// gitignores.
507	    ///
508	    /// When `None`, the CWD is fetched from `std::env::current_dir()`. If
509	    /// that fails, then global gitignores are ignored (an error is logged).
510	    global_gitignores_relative_to:
511	        OnceLock<Result<PathBuf, Arc<std::io::Error>>>,
512	}
513	
514	#[derive(Clone)]
515	enum Sorter {
516	    ByName(Arc<dyn Fn(&OsStr, &OsStr) -> Ordering + Send + Sync + 'static>),
517	    ByPath(Arc<dyn Fn(&Path, &Path) -> Ordering + Send + Sync + 'static>),
518	}
519	
520	#[derive(Clone)]
521	struct Filter(Arc<dyn Fn(&DirEntry) -> bool + Send + Sync + 'static>);
522	
523	impl std::fmt::Debug for WalkBuilder {
524	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
525	        f.debug_struct("WalkBuilder")
526	            .field("paths", &self.paths)
527	            .field("ig_builder", &self.ig_builder)
528	            .field("max_depth", &self.max_depth)
529	            .field("min_depth", &self.min_depth)
530	            .field("max_filesize", &self.max_filesize)
531	            .field("follow_links", &self.follow_links)
532	            .field("same_file_system", &self.same_file_system)
533	            .field("sorter", &"<...>")
534	            .field("threads", &self.threads)
535	            .field("skip", &self.skip)
536	            .field("filter", &"<...>")
537	            .field(
538	                "global_gitignores_relative_to",
539	                &self.global_gitignores_relative_to,
540	            )
541	            .finish()
542	    }
543	}
544	
545	impl WalkBuilder {
546	    /// Create a new builder for a recursive directory iterator for the
547	    /// directory given.
548	    ///
549	    /// Note that if you want to traverse multiple different directories, it
550	    /// is better to call `add` on this builder than to create multiple
551	    /// `Walk` values.
552	    pub fn new<P: AsRef<Path>>(path: P) -> WalkBuilder {
553	        WalkBuilder::from_iter([path])
554	    }
555	
556	    /// Create an empty builder to which paths can be added.
557	    ///
558	    /// Note that if you call `build` on this instance before calling `add`
559	    /// on it, it will return exactly zero items during iteration.
560	    pub fn empty() -> WalkBuilder {
561	        WalkBuilder {
562	            paths: vec![],
563	            ig_builder: IgnoreBuilder::new(),
564	            max_depth: None,
565	            min_depth: None,
566	            max_filesize: None,
567	            follow_links: false,
568	            same_file_system: false,
569	            sorter: None,
570	            threads: 0,
571	            skip: None,
572	            filter: None,
573	            global_gitignores_relative_to: OnceLock::new(),
574	        }
575	    }
576	
577	    /// Create a new builder for a recursive directory iterator from the
578	    /// sequence of paths.
579	    ///
580	    /// Note that if the iterator is empty, this is the same as
581	    /// `WalkBuilder::empty`.
582	    pub fn from_iter<P: AsRef<Path>, I: IntoIterator<Item = P>>(
583	        paths: I,
584	    ) -> WalkBuilder {
585	        let mut builder = WalkBuilder::empty();
586	        for path in paths.into_iter() {
587	            builder.add(path);
588	        }
589	        builder
590	    }
591	
592	    /// Build a new `Walk` iterator.
593	    pub fn build(&self) -> Walk {
594	        let follow_links = self.follow_links;
595	        let max_depth = self.max_depth;
596	        let min_depth = self.min_depth;
597	        let sorter = self.sorter.clone();
598	        let its = self
599	            .paths
600	            .iter()
601	            .map(move |p| {
602	                if p == Path::new("-") {
603	                    (p.to_path_buf(), None)
604	                } else {
605	                    let mut wd = WalkDir::new(p);
606	                    wd = wd.follow_links(follow_links || p.is_file());
607	                    wd = wd.same_file_system(self.same_file_system);
608	                    if let Some(max_depth) = max_depth {
609	                        wd = wd.max_depth(max_depth);
610	                    }
611	                    if let Some(min_depth) = min_depth {
612	                        wd = wd.min_depth(min_depth);
613	                    }
614	                    if let Some(ref sorter) = sorter {
615	                        match sorter.clone() {
616	                            Sorter::ByName(cmp) => {
617	                                wd = wd.sort_by(move |a, b| {
618	                                    cmp(a.file_name(), b.file_name())
619	                                });
620	                            }
621	                            Sorter::ByPath(cmp) => {
622	                                wd = wd.sort_by(move |a, b| {
623	                                    cmp(a.path(), b.path())
624	                                });
625	                            }
626	                        }
627	                    }
628	                    (p.to_path_buf(), Some(WalkEventIter::from(wd)))
629	                }
630	            })
631	            .collect::<Vec<_>>()
632	            .into_iter();
633	        let ig_root = self.build_ignore();
634	        Walk {
635	            its,
636	            it: None,
637	            ig_root: ig_root.clone(),
638	            ig: ig_root.clone(),
639	            max_depth: self.max_depth,
640	            max_filesize: self.max_filesize,
641	            skip: self.skip.clone(),
642	            filter: self.filter.clone(),
643	        }
644	    }
645	
646	    /// Build matchers for checking paths against ignore files without
647	    /// recursively walking the configured roots.
648	    ///
649	    /// The returned matchers use the path-based filtering configuration
650	    /// on this builder, including glob overrides, file type selections,
651	    /// parent ignore files, `.ignore`, `.gitignore`, global Git
652	    /// ignore files, explicitly added ignore files and custom ignore
653	    /// file names. For example, ripgrep configures `.rgignore` via
654	    /// [`WalkBuilder::add_custom_ignore_filename`]. Minimum and maximum depth
655	    /// limits, maximum file size and hidden-file filtering are also applied.
656	    /// Other options that only control traversal or require a directory entry,
