1156	        // expensive operations (stat, filesystem other) are done. This seems
1157	        // like an obvious optimization but becomes critical when filesystem
1158	        // operations even as simple as stat can result in significant
1159	        // overheads; an example of this was a bespoke filesystem layer in
1160	        // Windows that hosted files remotely and would download them on-demand
1161	        // when particular filesystem operations occurred. Users of this system
1162	        // who ensured correct file-type filters were being used could still
1163	        // get unnecessary file access resulting in large downloads.
1164	        if should_skip_entry(&self.ig, ent) {
1165	            return Ok(true);
1166	        }
1167	        if let Some(ref stdout) = self.skip {
1168	            if path_equals(ent, stdout)? {
1169	                return Ok(true);
