1195	                Some(ev) => ev,
1196	                None => {
1197	                    match self.its.next() {
1198	                        None => return None,
1199	                        Some((_, None)) => {
1200	                            return Some(Ok(DirEntry::new_stdin()));
1201	                        }
1202	                        Some((path, Some(it))) => {
1203	                            self.it = Some(it);
1204	                            if path.is_dir() {
1205	                                let (ig, err) = self.ig_root.add_parents(path);
1206	                                self.ig = ig;
1207	                                if let Some(err) = err {
