1426	impl WalkParallel {
1427	    /// Execute the parallel recursive directory iterator. `mkf` is called
1428	    /// for each thread used for iteration. The function produced by `mkf`
1429	    /// is then in turn called for each visited file path.
1430	    pub fn run<'s, F>(self, mkf: F)
1431	    where
1432	        F: FnMut() -> FnVisitor<'s>,
1433	    {
1434	        self.visit(&mut FnBuilder { builder: mkf })
1435	    }
