1437	    /// Execute the parallel recursive directory iterator using a custom
1438	    /// visitor.
1439	    ///
1440	    /// The builder given is used to construct a visitor for every thread
1441	    /// used by this traversal. The visitor returned from each builder is then
1442	    /// called for every directory entry seen by that thread.
1443	    ///
1444	    /// Typically, creating a custom visitor is useful if you need to perform
1445	    /// some kind of cleanup once traversal is finished. This can be achieved
1446	    /// by implementing `Drop` for your builder (or for your visitor, if you
1447	    /// want to execute cleanup for every thread that is launched).
1448	    ///
1449	    /// For example, each visitor might build up a data structure of results
1450	    /// corresponding to the directory entries seen for each thread. Since each
1451	    /// visitor runs on only one thread, this build-up can be done without
1452	    /// synchronization. Then, once traversal is complete, all of the results
1453	    /// can be merged together into a single data structure.
1454	    pub fn visit(mut self, builder: &mut dyn ParallelVisitorBuilder<'_>) {
1455	        let threads = self.threads();
1456	        let mut stack = vec![];
1457	        {
1458	            let mut visitor = builder.build();
1459	            let mut paths = Vec::new().into_iter();
1460	            std::mem::swap(&mut paths, &mut self.paths);
1461	            // Send the initial set of root paths to the pool of workers. Note
1462	            // that we only send directories. For files, we send to them the
1463	            // callback directly.
1464	            for path in paths {
1465	                let (dent, root_device) = if path == Path::new("-") {
1466	                    (DirEntry::new_stdin(), None)
1467	                } else {
1468	                    let root_device = if !self.same_file_system {
1469	                        None
1470	                    } else {
1471	                        match device_num(&path) {
1472	                            Ok(root_device) => Some(root_device),
1473	                            Err(err) => {
1474	                                let err = Error::Io(err).with_path(path);
1475	                                if visitor.visit(Err(err)).is_quit() {
1476	                                    return;
1477	                                }
1478	                                continue;
1479	                            }
1480	                        }
1481	                    };
1482	                    match DirEntryRaw::from_path(0, path, false) {
1483	                        Ok(dent) => {
1484	                            (DirEntry::new_raw(dent, None), root_device)
1485	                        }
1486	                        Err(err) => {
1487	                            if visitor.visit(Err(err)).is_quit() {
1488	                                return;
1489	                            }
1490	                            continue;
1491	                        }
1492	                    }
1493	                };
1494	                stack.push(Message::Work(Work {
1495	                    dent,
1496	                    ignore: self.ig_root.clone(),
1497	                    root_device,
1498	                }));
1499	            }
1500	            // ... but there's no need to start workers if we don't need them.
1501	            if stack.is_empty() {
1502	                return;
1503	            }
1504	        }
1505	        // Create the workers and then wait for them to finish.
1506	        let quit_now = Arc::new(AtomicBool::new(false));
1507	        let active_workers = Arc::new(AtomicUsize::new(threads));
1508	        let stacks = Stack::new_for_each_thread(threads, stack);
1509	        // Collect all of the workers first. In the case that
1510	        // `builder.build()` panics, we want that to happen and
1511	        // propagate before we actually start to run any of the
1512	        // workers.
1513	        let workers: Vec<_> = stacks
1514	            .into_iter()
1515	            .map(|stack| Worker {
1516	                visitor: builder.build(),
1517	                stack,
1518	                quit_now: quit_now.clone(),
1519	                active_workers: active_workers.clone(),
1520	                max_depth: self.max_depth,
1521	                min_depth: self.min_depth,
1522	                max_filesize: self.max_filesize,
1523	                follow_links: self.follow_links,
1524	                skip: self.skip.clone(),
1525	                filter: self.filter.clone(),
1526	            })
1527	            .collect();
1528	        std::thread::scope(|s| {
1529	            let handles: Vec<_> = workers
1530	                .into_iter()
1531	                .map(|worker| s.spawn(|| worker.run()))
1532	                .collect();
1533	            for handle in handles {
1534	                handle.join().unwrap();
1535	            }
1536	        });
1537	    }
1538	
1539	    fn threads(&self) -> usize {
1540	        if self.threads == 0 {
1541	            std::thread::available_parallelism().map_or(1, |n| n.get()).min(12)
1542	        } else {
1543	            self.threads
1544	        }
1545	    }
1546	}
