1578	impl Work {
1579	    /// Returns true if and only if this work item is a directory.
1580	    fn is_dir(&self) -> bool {
1581	        self.dent.is_dir()
1582	    }
1583	
1584	    /// Returns true if and only if this work item is a symlink.
1585	    fn is_symlink(&self) -> bool {
1586	        self.dent.file_type().map_or(false, |ft| ft.is_symlink())
1587	    }
1588	
1589	    /// Adds ignore rules for parent directories.
1590	    ///
1591	    /// Note that this only applies to entries at depth 0. On all other
1592	    /// entries, this is a no-op.
1593	    fn add_parents(&mut self) -> Option<Error> {
1594	        if self.dent.depth() > 0 {
1595	            return None;
1596	        }
1597	        // At depth 0, the path of this entry is a root path, so we can
1598	        // use it directly to add parent ignore rules.
1599	        let (ig, err) = self.ignore.add_parents(self.dent.path());
1600	        self.ignore = ig;
1601	        err
1602	    }
1603	
1604	    /// Adds ignore rules for this directory without reading its contents.
1605	    fn add_ignore(&mut self) {
1606	        let (ig, err) = self.ignore.add_child(self.dent.path());
1607	        self.ignore = ig;
1608	        self.dent.err = err;
1609	    }
1610	
1611	    /// Reads the directory contents of this work item and adds ignore
1612	    /// rules for this directory.
1613	    ///
1614	    /// If there was a problem with reading the directory contents, then
1615	    /// an error is returned. If there was a problem reading the ignore
1616	    /// rules for this directory, then the error is attached to this
1617	    /// work item's directory entry.
1618	    fn read_dir(&mut self) -> Result<ReadDirResult, Error> {
1619	        let readdir = match fs::read_dir(self.dent.path()) {
1620	            Ok(readdir) => readdir,
1621	            Err(err) => {
1622	                let err = Error::from(err)
1623	                    .with_path(self.dent.path())
1624	                    .with_depth(self.dent.depth());
1625	                return Err(err);
1626	            }
1627	        };
1628	        // Actually descend into the directory and read its contents
1629	        let mut result = ReadDirResult::default();
1630	        for entry in readdir {
1631	            match entry {
1632	                Ok(entry) => result.entries.push(entry),
1633	                Err(err) => result.errors.push(
1634	                    Error::from(err)
1635	                        .with_path(self.dent.path())
1636	                        .with_depth(self.dent.depth() + 1),
1637	                ),
1638	            }
1639	        }
1640	        let (ig, err) = self
1641	            .ignore
1642	            .add_child_with_entries(self.dent.path(), &result.entries);
1643	        self.ignore = ig;
1644	        self.dent.err = err;
1645	        Ok(result)
1646	    }
1647	}
