1649	/// A work-stealing stack.
1650	#[derive(Debug)]
1651	struct Stack {
1652	    /// This thread's index.
1653	    index: usize,
1654	    /// The thread-local stack.
1655	    deque: Deque<Message>,
1656	    /// The work stealers.
1657	    stealers: Arc<[Stealer<Message>]>,
1658	}
1659	
1660	impl Stack {
1661	    /// Create a work-stealing stack for each thread. The given messages
1662	    /// correspond to the initial paths to start the search at. They will
1663	    /// be distributed automatically to each stack in a round-robin fashion.
1664	    fn new_for_each_thread(threads: usize, init: Vec<Message>) -> Vec<Stack> {
1665	        // Using new_lifo() ensures each worker operates depth-first, not
1666	        // breadth-first. We do depth-first because a breadth first traversal
1667	        // on wide directories with a lot of gitignores is disastrous (for
1668	        // example, searching a directory tree containing all of crates.io).
1669	        let deques: Vec<Deque<Message>> =
1670	            std::iter::repeat_with(Deque::new_lifo).take(threads).collect();
1671	        let stealers = Arc::<[Stealer<Message>]>::from(
1672	            deques.iter().map(Deque::stealer).collect::<Vec<_>>(),
1673	        );
1674	        let stacks: Vec<Stack> = deques
1675	            .into_iter()
1676	            .enumerate()
1677	            .map(|(index, deque)| Stack {
1678	                index,
1679	                deque,
1680	                stealers: stealers.clone(),
1681	            })
1682	            .collect();
1683	        // Distribute the initial messages, reverse the order to cancel out
1684	        // the other reversal caused by the inherent LIFO processing of the
1685	        // per-thread stacks which are filled here.
1686	        init.into_iter()
1687	            .rev()
1688	            .zip(stacks.iter().cycle())
1689	            .for_each(|(m, s)| s.push(m));
1690	        stacks
1691	    }
1692	
1693	    /// Push a message.
1694	    fn push(&self, msg: Message) {
1695	        self.deque.push(msg);
1696	    }
1697	
1698	    /// Pop a message.
1699	    fn pop(&self) -> Option<Message> {
1700	        self.deque.pop().or_else(|| self.steal())
1701	    }
1702	
1703	    /// Steal a message from another queue.
1704	    fn steal(&self) -> Option<Message> {
1705	        // For fairness, try to steal from index + 1, index + 2, ... len - 1,
1706	        // then wrap around to 0, 1, ... index - 1.
1707	        let (left, right) = self.stealers.split_at(self.index);
1708	        // Don't steal from ourselves
1709	        let right = &right[1..];
1710	
1711	        right
1712	            .iter()
1713	            .chain(left.iter())
1714	            .map(|s| s.steal_batch_and_pop(&self.deque))
1715	            .find_map(|s| s.success())
1716	    }
1717	}
