1719	/// A worker is responsible for descending into directories, updating the
1720	/// ignore matchers, producing new work and invoking the caller's callback.
1721	///
1722	/// Note that a worker is *both* a producer and a consumer.
1723	struct Worker<'s> {
1724	    /// The caller's callback.
1725	    visitor: Box<dyn ParallelVisitor + 's>,
1726	    /// A work-stealing stack of work to do.
1727	    ///
1728	    /// We use a stack instead of a channel because a stack lets us visit
1729	    /// directories in depth first order. This can substantially reduce peak
1730	    /// memory usage by keeping both the number of file paths and gitignore
1731	    /// matchers in memory lower.
1732	    stack: Stack,
1733	    /// Whether all workers should terminate at the next opportunity. Note
1734	    /// that we need this because we don't want other `Work` to be done after
1735	    /// we quit. We wouldn't need this if have a priority channel.
1736	    quit_now: Arc<AtomicBool>,
1737	    /// The number of currently active workers.
1738	    active_workers: Arc<AtomicUsize>,
1739	    /// The maximum depth of directories to descend. A value of `0` means no
1740	    /// descension at all.
1741	    max_depth: Option<usize>,
1742	    /// The minimum depth of directories to descend.
1743	    min_depth: Option<usize>,
1744	    /// The maximum size a searched file can be (in bytes). If a file exceeds
1745	    /// this size it will be skipped.
1746	    max_filesize: Option<u64>,
1747	    /// Whether to follow symbolic links or not. When this is enabled, loop
1748	    /// detection is performed.
1749	    follow_links: bool,
1750	    /// A file handle to skip, currently is either `None` or stdout, if it's
1751	    /// a file and it has been requested to skip files identical to stdout.
1752	    skip: Option<Arc<Handle>>,
1753	    /// A predicate applied to dir entries. If true, the entry and all
1754	    /// children will be skipped.
1755	    filter: Option<Filter>,
1756	}
1757	
1758	impl<'s> Worker<'s> {
1759	    /// Runs this worker until there is no more work left to do.
1760	    ///
1761	    /// The worker will call the caller's callback for all entries that aren't
1762	    /// skipped by the ignore matcher.
1763	    fn run(mut self) {
1764	        while let Some(work) = self.get_work() {
1765	            if let WalkState::Quit = self.run_one(work) {
1766	                self.quit_now();
1767	            }
1768	        }
1769	    }
1770	
1771	    fn run_one(&mut self, mut work: Work) -> WalkState {
1772	        let should_visit = self
1773	            .min_depth
1774	            .map(|min_depth| work.dent.depth() >= min_depth)
1775	            .unwrap_or(true);
1776	
1777	        // If the work is not a directory, then we can just execute the
1778	        // caller's callback immediately and move on.
1779	        if work.is_symlink() || !work.is_dir() {
1780	            return if should_visit {
1781	                self.visitor.visit(Ok(work.dent))
1782	            } else {
1783	                WalkState::Continue
1784	            };
1785	        }
1786	        if let Some(err) = work.add_parents() {
1787	            let state = self.visitor.visit(Err(err));
1788	            if state.is_quit() {
1789	                return state;
1790	            }
1791	        }
1792	
1793	        let descend = if let Some(root_device) = work.root_device {
1794	            match is_same_file_system(root_device, work.dent.path()) {
1795	                Ok(true) => true,
1796	                Ok(false) => false,
1797	                Err(err) => {
1798	                    let state = self.visitor.visit(Err(err));
1799	                    if state.is_quit() {
1800	                        return state;
1801	                    }
1802	                    false
1803	                }
1804	            }
1805	        } else {
1806	            true
1807	        };
1808	
1809	        // Try to read the directory first before we transfer ownership
1810	        // to the provided closure. Do not unwrap it immediately, though,
1811	        // as we may receive an `Err` value e.g. in the case when we do not
1812	        // have sufficient read permissions to list the directory.
1813	        // In that case we still want to provide the closure with a valid
1814	        // entry before passing the error value.
1815	        let depth = work.dent.depth();
1816	        let readdir = if descend && self.max_depth.is_none_or(|m| depth < m) {
1817	            Some(work.read_dir())
1818	        } else {
1819	            work.add_ignore();
1820	            None
1821	        };
1822	        if should_visit {
1823	            let state = self.visitor.visit(Ok(work.dent));
1824	            if !state.is_continue() {
1825	                return state;
1826	            }
1827	        }
1828	        if !descend {
1829	            return WalkState::Skip;
1830	        }
1831	
1832	        let readdir = match readdir {
1833	            Some(readdir) => readdir,
1834	            None => return WalkState::Skip,
1835	        };
1836	        let readdir = match readdir {
1837	            Ok(readdir) => readdir,
1838	            Err(err) => {
1839	                return self.visitor.visit(Err(err));
1840	            }
1841	        };
1842	
1843	        for result in readdir.entries {
1844	            let state = self.generate_work(
1845	                &work.ignore,
1846	                depth + 1,
1847	                work.root_device,
1848	                result,
1849	            );
1850	            if state.is_quit() {
1851	                return state;
1852	            }
1853	        }
1854	        for err in readdir.errors {
1855	            let state = self.visitor.visit(Err(err));
1856	            if state.is_quit() {
1857	                return state;
1858	            }
1859	        }
1860	        WalkState::Continue
1861	    }
1862	
1863	    /// Decides whether to submit the given directory entry as a file to
1864	    /// search.
1865	    ///
1866	    /// If the entry is a path that should be ignored, then this is a no-op.
1867	    /// Otherwise, the entry is pushed on to the queue. (The actual execution
1868	    /// of the callback happens in `run_one`.)
1869	    ///
1870	    /// If an error occurs while reading the entry, then it is sent to the
1871	    /// caller's callback.
1872	    ///
1873	    /// `ig` is the `Ignore` matcher for the parent directory. `depth` should
1874	    /// be the depth of this entry. `result` should be the item yielded by
1875	    /// a directory iterator.
1876	    fn generate_work(
1877	        &mut self,
1878	        ig: &Ignore,
1879	        depth: usize,
1880	        root_device: Option<u64>,
1881	        fs_dent: fs::DirEntry,
1882	    ) -> WalkState {
1883	        let mut dent = match DirEntryRaw::from_entry(depth, &fs_dent) {
1884	            Ok(dent) => DirEntry::new_raw(dent, None),
1885	            Err(err) => {
1886	                return self.visitor.visit(Err(err));
1887	            }
1888	        };
1889	        let is_symlink = dent.file_type().map_or(false, |ft| ft.is_symlink());
1890	        if self.follow_links && is_symlink {
1891	            let path = dent.path().to_path_buf();
1892	            dent = match DirEntryRaw::from_path(depth, path, true) {
1893	                Ok(dent) => DirEntry::new_raw(dent, None),
1894	                Err(err) => {
1895	                    return self.visitor.visit(Err(err));
1896	                }
1897	            };
1898	            if dent.is_dir() {
1899	                if let Err(err) = check_symlink_loop(ig, dent.path(), depth) {
1900	                    return self.visitor.visit(Err(err));
1901	                }
1902	            }
1903	        }
1904	        // N.B. See analogous call in the single-threaded implementation about
1905	        // why it's important for this to come before the checks below.
1906	        if should_skip_entry(ig, &dent) {
1907	            return WalkState::Continue;
1908	        }
1909	        if let Some(ref stdout) = self.skip {
1910	            let is_stdout = match path_equals(&dent, stdout) {
1911	                Ok(is_stdout) => is_stdout,
1912	                Err(err) => return self.visitor.visit(Err(err)),
1913	            };
1914	            if is_stdout {
1915	                return WalkState::Continue;
1916	            }
1917	        }
1918	        let should_skip_filesize =
1919	            if self.max_filesize.is_some() && !dent.is_dir() {
1920	                skip_filesize(
1921	                    self.max_filesize.unwrap(),
1922	                    dent.path(),
1923	                    &dent.metadata().ok(),
1924	                )
1925	            } else {
1926	                false
1927	            };
1928	        let should_skip_filtered =
1929	            if let Some(Filter(predicate)) = &self.filter {
1930	                !predicate(&dent)
1931	            } else {
1932	                false
1933	            };
1934	        if !should_skip_filesize && !should_skip_filtered {
1935	            self.send(Work { dent, ignore: ig.clone(), root_device });
1936	        }
1937	        WalkState::Continue
1938	    }
1939	
1940	    /// Returns the next directory to descend into.
1941	    ///
1942	    /// If all work has been exhausted, then this returns None. The worker
1943	    /// should then subsequently quit.
1944	    fn get_work(&mut self) -> Option<Work> {
1945	        let mut value = self.recv();
1946	        loop {
1947	            // Simulate a priority channel: If quit_now flag is set, we can
1948	            // receive only quit messages.
1949	            if self.is_quit_now() {
1950	                value = Some(Message::Quit)
1951	            }
1952	            match value {
1953	                Some(Message::Work(work)) => {
1954	                    return Some(work);
1955	                }
1956	                Some(Message::Quit) => {
1957	                    // Repeat quit message to wake up sleeping threads, if
1958	                    // any. The domino effect will ensure that every thread
1959	                    // will quit.
1960	                    self.send_quit();
1961	                    return None;
1962	                }
1963	                None => {
1964	                    if self.deactivate_worker() == 0 {
1965	                        // If deactivate_worker() returns 0, every worker thread
1966	                        // is currently within the critical section between the
1967	                        // acquire in deactivate_worker() and the release in
1968	                        // activate_worker() below.  For this to happen, every
1969	                        // worker's local deque must be simultaneously empty,
1970	                        // meaning there is no more work left at all.
1971	                        self.send_quit();
1972	                        return None;
1973	                    }
1974	                    // Wait for next `Work` or `Quit` message.
1975	                    loop {
1976	                        if self.is_quit_now() {
1977	                            return None;
1978	                        }
1979	                        if let Some(v) = self.recv() {
1980	                            self.activate_worker();
1981	                            value = Some(v);
1982	                            break;
1983	                        }
1984	                        // Our stack isn't blocking. Instead of burning the
1985	                        // CPU waiting, we let the thread sleep for a bit. In
1986	                        // general, this tends to only occur once the search is
1987	                        // approaching termination.
1988	                        let dur = std::time::Duration::from_millis(1);
1989	                        std::thread::sleep(dur);
1990	                    }
1991	                }
1992	            }
1993	        }
1994	    }
1995	
1996	    /// Indicates that all workers should quit immediately.
1997	    fn quit_now(&self) {
1998	        self.quit_now.store(true, AtomicOrdering::SeqCst);
1999	    }
2000	
2001	    /// Returns true if this worker should quit immediately.
2002	    fn is_quit_now(&self) -> bool {
2003	        self.quit_now.load(AtomicOrdering::SeqCst)
2004	    }
2005	
2006	    /// Send work.
2007	    fn send(&self, work: Work) {
2008	        self.stack.push(Message::Work(work));
2009	    }
2010	
2011	    /// Send a quit message.
2012	    fn send_quit(&self) {
2013	        self.stack.push(Message::Quit);
2014	    }
2015	
2016	    /// Receive work.
2017	    fn recv(&self) -> Option<Message> {
2018	        self.stack.pop()
2019	    }
2020	
2021	    /// Deactivates a worker and returns the number of currently active workers.
2022	    fn deactivate_worker(&self) -> usize {
2023	        self.active_workers.fetch_sub(1, AtomicOrdering::Acquire) - 1
2024	    }
2025	
2026	    /// Reactivates a worker.
2027	    fn activate_worker(&self) {
2028	        self.active_workers.fetch_add(1, AtomicOrdering::Release);
2029	    }
2030	}
2031	
2032	impl<'s> Drop for Worker<'s> {
2033	    fn drop(&mut self) {
2034	        if std::thread::panicking() {
2035	            self.quit_now();
2036	        }
2037	    }
2038	}
2039	
2040	fn check_symlink_loop(
2041	    ig_parent: &Ignore,
2042	    child_path: &Path,
2043	    child_depth: usize,
2044	) -> Result<(), Error> {
2045	    let hchild = Handle::from_path(child_path).map_err(|err| {
2046	        Error::from(err).with_path(child_path).with_depth(child_depth)
2047	    })?;
2048	    for ig in ig_parent.parents().take_while(|ig| !ig.is_absolute_parent()) {
2049	        let h = Handle::from_path(ig.path()).map_err(|err| {
2050	            Error::from(err).with_path(child_path).with_depth(child_depth)
2051	        })?;
2052	        if hchild == h {
2053	            return Err(Error::Loop {
2054	                ancestor: ig.path().to_path_buf(),
2055	                child: child_path.to_path_buf(),
2056	            }
2057	            .with_depth(child_depth));
2058	        }
2059	    }
2060	    Ok(())
2061	}
2062	
2063	// Before calling this function, make sure that you ensure that is really
2064	// necessary as the arguments imply a file stat.
2065	fn skip_filesize(
2066	    max_filesize: u64,
2067	    path: &Path,
2068	    ent: &Option<Metadata>,
2069	) -> bool {
2070	    let filesize = match *ent {
2071	        Some(ref md) => Some(md.len()),
2072	        None => None,
2073	    };
2074	
2075	    if let Some(fs) = filesize {
2076	        if fs > max_filesize {
2077	            log::debug!("ignoring {}: {} bytes", path.display(), fs);
2078	            true
2079	        } else {
2080	            false
2081	        }
2082	    } else {
2083	        false
2084	    }
2085	}
2086	
2087	fn should_skip_entry(ig: &Ignore, dent: &DirEntry) -> bool {
2088	    let m = ig.matched_dir_entry(dent);
2089	    if m.is_ignore() {
2090	        log::debug!("ignoring {}: {:?}", dent.path().display(), m);
2091	        true
2092	    } else if m.is_whitelist() {
2093	        log::debug!("whitelisting {}: {:?}", dent.path().display(), m);
2094	        false
2095	    } else {
2096	        false
2097	    }
2098	}
