    fs::write(td.join("src/.ignore"), "!keep.tmp\n").unwrap();
    fs::write(td.join("src/keep.tmp"), "").unwrap();
    fs::write(td.join("src/drop.tmp"), "").unwrap();
    fs::write(td.join("src/deep/data.txt"), "").unwrap();
    fs::write(td.join("blocked/hidden.txt"), "").unwrap();

    let mut b = WalkBuilder::new(&td);
    b.min_depth(Some(2)).max_depth(Some(3));
    for mode in ["serial", "parallel"] {
        let mut got = vec![];
        if mode == "serial" {
            for r in b.build() {
                match r {
                    Ok(e) => got.push(format!("{:?} depth={}", e.path().strip_prefix(&td).unwrap(), e.depth())),
                    Err(e) => got.push(format!("ERR: {e}")),
                }
            }
        } else {
            let td = td.clone();
            let got2 = std::sync::Arc::new(std::sync::Mutex::new(vec![]));
            let g = got2.clone();
            b.build_parallel().run(|| {
                let td = td.clone();
                let g = g.clone();
                Box::new(move |r| {
                    match r {
                        Ok(e) => g.lock().unwrap().push(format!("{:?} depth={}", e.path().strip_prefix(&td).unwrap(), e.depth())),
                        Err(e) => g.lock().unwrap().push(format!("ERR: {e}")),
                    }
                    ignore::WalkState::Continue
                })
            });
            got = std::mem::take(&mut *got2.lock().unwrap());
        }
        got.sort();
        println!("--- {mode} (min 2, max 3) ---");
        for line in got { println!("{line}"); }
    }
}
